head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gReqAcptNo;
scwin.gAnsRnd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gInputTp;
scwin.vScrenID = 'ULDSTF30202.xml';X < !정보--;
셋팅-- > function() {
    scwin.gReqAcptNo = $c.frame.path("../").scwin.gReqAcptNo;
    scwin.gAnsRnd = $c.frame.path("../").scwin.gAnsRnd;
    //alert("자식창:"+gReqAcptNo+","+ gAnsRnd);

} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/InquiryDisclosure.do?method=readInquiryDsclAns" + "&inputMessageId=INQDISCLSANS_INOUT" + "&outputMessageId=INQDISCLSANS_INOUT" + "&REQ_ACPT_NO=" + scwin.gReqAcptNo + "&ANS_RND=" + scwin.gAnsRnd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_inquiry_info.DataID = encodeURI(url);
    dts_inquiry_info.reset();
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Update = function() {
    var vDeadlineDd = $c.stf.getObjectValue(edt_deadline_dd);
    if (vDeadlineDd.length < 8) {
        $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_deadline_dd.focus();
        return;
    }
    dts_inquiry.insertRow();
    dts_inquiry.setCellData(1, "REQ_ACPT_NO", scwin.gReqAcptNo);
    dts_inquiry.setCellData(1, "ANS_RND", scwin.gAnsRnd);
    dts_inquiry.setCellData(1, "ADM_DEADLINE", vDeadlineDd);
    dts_inquiry.setCellData(1, "FINAL_YN", $c.stf.getObjectValue(cmb_final_yn));
    dts_inquiry.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));

    //alert(dts_nfaith.text);

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_inquiry_info.Action = "/InquiryDisclosure.do?method=modifyInquiryDsclAns&inputMessageId=INQDISCLSANS_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_inquiry_info.KeyName = "toinb_dataid4";
        trs_inquiry_info.KeyValue = "JSP(I:pInput=dts_inquiry)";
        trs_inquiry_info.Post();
    }
};




// 답변연결 삭제(담당자가 수동으로 연결한것)
scwin.fn_Delete = function() {
    if (scwin.gInputTp == 'A') {
        $c.win.alert("상장법인이 제출한 조회공시답변은 삭제하실 수 없습니다.");
        edt_deadline_dd.focus();
        return;
    }
    var rtn = confirm('조회공시 답변을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_inquiry.insertRow();
        dts_inquiry.setCellData(1, "REQ_ACPT_NO", scwin.gReqAcptNo);
        dts_inquiry.setCellData(1, "ANS_RND", scwin.gAnsRnd);
        trs_inquiry_info.Action = "/InquiryDisclosure.do?method=removeInquiryDsclAns&inputMessageId=INQDISCLSANS_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry_info.KeyName = "toinb_dataid4";
        trs_inquiry_info.KeyValue = "JSP(I:pInput=dts_inquiry)";
        trs_inquiry_info.Post();
    }
};
scwin.img_cls_dd_onclick = function() {
    popUpCalendar2(edt_deadline_dd);
};
scwin.btn_Close_onclick = async function() {
    //self.close();
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Update();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.dts_inquiry_info_OnLoadError = function() {
    $c.stf.alert_error(dts_inquiry_info);
};
scwin.dts_inquiry_info_OnLoadCompleted = function(rowcount) {
    var vProcsEmpNo = dts_inquiry_info.getCellData(1, "EMP_NO");
    if (vProcsEmpNo != '') {
        scwin.gInputTp = 'M'; // 담당자가 수동으로 답변연결한 경우
        $c.stf.showObj(btn_Delete, true);
    } else {
        scwin.gInputTp = 'A'; // 상장법인이 제출에서 답변을 제출한 경우
        $c.stf.showObj(btn_Delete, false);
    }
};
scwin.trs_inquiry_info_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    //self.close();
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_inquiry_info_OnFail = function() {
    $c.win.alert('trs_inquiry_info.OnFail() :' + trs_inquiry_info.ErrorMsg);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_inquiry_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INQDISCLSANS_INOUT";
    dts_inquiry_info.reset();
    // 가우스헤더 셋팅
    dts_inquiry.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INQDISCLSANS_INOUT";
    dts_inquiry.reset();

    //  정보 읽어오기
    fn_ReadInfo();
};
